  await page.goto('http://localhost:3000', { waitUntil: 'load' });
  await page.waitForTimeout(500);
  await page.locator('.rail-chip[data-value="25"]').click();
  await page.locator('.rail-chip[data-value="100"]').click();
  const metrics = await page.evaluate(() => {
    const r = sel => { const el = document.querySelector(sel); if (!el) return null; const b = el.getBoundingClientRect(); return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height) }; };
    return {
      scrollH: document.documentElement.scrollHeight,
      clientH: document.documentElement.clientHeight,
      bodyScroll: document.body.scrollHeight,
      table: r('.table'),
      controls: r('#controls'),
      railTop: r('.rail-chip[data-value="25"]'),
      railRight: r('.rail-chip[data-value="500"]'),
      hud: r('.hud'),
      status: r('.status-row'),
      betspot: r('#bet-player'),
    };
  });
  console.log(name, JSON.stringify(metrics));
  await page.screenshot({ path: `screenshots/${name}-bet.jpg`, type: 'jpeg', quality: 82 });
  await page.locator('#primaryBtn').click();
  await page.waitForTimeout(3200);
  const dealMetrics = await page.evaluate(() => {
    const r = sel => { const el = document.querySelector(sel); if (!el) return null; const b = el.getBoundingClientRect(); return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height) }; };
    return {
      phase: window.__goldenAce.state.phase,
      status: document.getElementById('statusText').textContent,
      playerHand: r('#hand-player'),
      dealerHand: r('#hand-dealer'),
      playerCards: document.querySelectorAll('#hand-player .card').length,
      tableBottom: r('.table')?.y + r('.table')?.h,
      railTop: r('.rail-chip[data-value="25"]')?.y,
      betspot: r('#bet-player'),
    };
  });
  console.log(name, 'deal', JSON.stringify(dealMetrics));
  await page.screenshot({ path: `screenshots/${name}-turn.jpg`, type: 'jpeg', quality: 82 });
  await page.close();
}
console.log('errors:', errors.length ? errors : 'none');
await browser.close();

