import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.waitForTimeout(500);

const results = await page.evaluate(() => {
  const g = window.__goldenAce;
  const C = (rank, suit = '♠') => ({ rank, suit, red: suit === '♥' || suit === '♦' });
  const out = [];
  const scenario = (name, playerCards, dealerCards, bet = 25, playerBal = 500) => {
    g.state.bankroll = playerBal;
    g.state.phase = 'result';
    g.state.bets = { player: bet, left: 0, right: 0 };
    g.state.hands = { player: playerCards, left: [], right: [], dealer: dealerCards };
    g.state.outcomes = {};
    g.settle();
    out.push({
      name,
      bankroll: g.state.bankroll,
      delta: Math.round((g.state.bankroll - playerBal) * 100) / 100,
      outcome: g.state.outcomes.player,
      dealerCaption: document.getElementById('caption-dealer').textContent,
    });
  };
  scenario('player blackjack vs 20', [C('A'), C('K')], [C('10'), C('Q')]);
  scenario('both blackjack', [C('A'), C('K')], [C('A'), C('Q')]);
  scenario('player 20 vs dealer bust', [C('10'), C('Q')], [C('10'), C('6'), C('9')]);
  scenario('push 19', [C('10'), C('9')], [C('10'), C('9')]);
  scenario('loss 18 vs 19', [C('9'), C('9')], [C('10'), C('9')]);
  scenario('dealer blackjack vs 20', [C('10'), C('Q')], [C('A'), C('K')]);
  scenario('player bust', [C('10'), C('6'), C('9')], [C('10'), C('8')]);
  scenario('blackjack $1 fractional', [C('A'), C('K')], [C('10'), C('Q')], 1);

  // AI side-bet settlement check.
  g.state.bankroll = 500;
  g.state.phase = 'result';
  g.state.bets = { player: 0, left: 10, right: 25 };
  g.state.ai.left.bal = 100;
  g.state.ai.right.bal = 100;
  g.state.hands = {
    player: [],
    left: [C('10'), C('9')],
    right: [C('10'), C('7')],
    dealer: [C('10'), C('8')],
  };
  g.state.outcomes = {};
  g.settle();
  out.push({
    name: 'AI settlement',
    bankroll: g.state.bankroll,
    aiLeft: g.state.ai.left.bal,
    aiRight: g.state.ai.right.bal,
    outcomes: g.state.outcomes,
  });
  return out;
});
console.log(JSON.stringify(results, null, 2));
console.log('errors:', errors.length ? errors : 'none');
await browser.close();

