import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.waitForTimeout(400);

const status = () => page.evaluate(() => ({
  phase: window.__goldenAce.state.phase,
  bankroll: window.__goldenAce.state.bankroll,
  bet: window.__goldenAce.state.bets.player,
  outcomes: window.__goldenAce.state.outcomes,
  values: Object.fromEntries(Object.entries(window.__goldenAce.state.hands).map(([k, v]) => [k, v.map(c => c.hidden ? '??' : c.rank + c.suit)])),
  statusText: document.getElementById('statusText').textContent,
  banner: document.getElementById('banner').textContent,
  controls: {
    primary: document.getElementById('primaryBtn').textContent,
    secondary: document.getElementById('secondaryBtn').textContent,
    secondaryDisplay: getComputedStyle(document.getElementById('secondaryBtn')).display,
  },
}));

for (let hand = 1; hand <= 5; hand++) {
  const before = await status();
  await page.locator('.rail-chip[data-value="25"]').click();
  await page.locator('#primaryBtn').click();
  // Wait for player turn, blackjack, or result.
  await page.waitForFunction(() => ['player', 'result'].includes(window.__goldenAce.state.phase), null, { timeout: 15000 });
  let mid = await status();
  if (mid.phase === 'player') {
    await page.locator('#primaryBtn').click();
  }
  await page.waitForFunction(() => window.__goldenAce.state.phase === 'result', null, { timeout: 20000 });
  await page.waitForTimeout(300);
  const after = await status();
  const bet = after.bet;
  const po = after.outcomes.player || { net: 0, label: 'NO BET' };
  const delta = Math.round((after.bankroll - before.bankroll) * 100) / 100;
  const expected = Math.round((po.net - bet) * 100) / 100;
  console.log(`hand ${hand}`, JSON.stringify({ before: before.bankroll, bet, delta, expected, net: po.net, label: po.label, onTable: after.values, status: after.statusText, banner: after.banner, controls: after.controls }));
  if (Math.abs(delta - expected) > 0.001) console.log('  !!! bankroll delta mismatch');
  await page.locator('#primaryBtn').click(); // next hand
  await page.waitForTimeout(300);
}

// Use HIT once and screenshot an active hand with the new label placement.
await page.locator('.rail-chip[data-value="5"]').click();
await page.locator('#primaryBtn').click();
await page.waitForFunction(() => window.__goldenAce.state.phase === 'player', null, { timeout: 15000 });
await page.locator('#secondaryBtn').click();
await page.waitForTimeout(700);
await page.screenshot({ path: 'screenshots/final-turn.jpg', type: 'jpeg', quality: 84 });
console.log('final phase', await page.evaluate(() => window.__goldenAce.state.phase));
console.log('errors:', errors.length ? errors : 'none');
await browser.close();

